'use strict';
// AI: below section was generated by an AI
// Scratch check (agent HOME): does /home/ws work in a real browser once wslib.js uses the RFC 6455 GUID?
// Loads ../server.js with require('./wslib.js') redirected to a scratch copy whose GUID is corrected (the shared file is
// not touched), opens /home in headless Chromium (Playwright already on this PC) and counts the page's /home/ws frames.
//   node browser_ws_check.js [--port 8098] [--broken]   (--broken: keep the original wslib.js, to see the failure)
process.env.HG_NO_SAVE = '1';
const fs = require('node:fs');
const path = require('node:path');
const Module = require('node:module');

const VDIR = path.join(__dirname, '..');
const PORT = String(process.argv.includes('--port') ? process.argv[process.argv.indexOf('--port') + 1] : 8098);
if (!process.argv.includes('--broken')) {
  const orig = path.join(VDIR, 'wslib.js');
  const fixed = path.join(__dirname, 'wslib_rfcguid.js');
  fs.writeFileSync(fixed, fs.readFileSync(orig, 'utf8').replace(/const GUID = '[^']*';/, "const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';"));
  const resolve = Module._resolveFilename;
  Module._resolveFilename = function (req, parent, ...rest) {
    const r = resolve.call(this, req, parent, ...rest);
    return r === orig ? fixed : r;
  };
}
process.argv.push('--port', PORT);
require(path.join(VDIR, 'server.js'));

(async () => {
  const pw = require(path.join(process.env.APPDATA, 'npm', 'node_modules', 'omniroute', 'node_modules', 'playwright'));
  await new Promise(r => setTimeout(r, 1500));
  const browser = await pw.chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  const ws = { opened: 0, frames: 0, bytes: new Set(), closed: 0 };
  page.on('websocket', s => {
    if (!s.url().includes('/home/ws')) return;
    ws.opened++;
    s.on('framereceived', f => { if (typeof f.payload !== 'string') { ws.frames++; ws.bytes.add(f.payload.length); } });
    s.on('close', () => { ws.closed++; });
  });
  await page.goto('http://127.0.0.1:' + PORT + '/home', { waitUntil: 'load' });
  await page.waitForTimeout(4000);
  console.log('page /home/ws: opened ' + ws.opened + ', binary frames ' + ws.frames + ' in ~4 s, sizes ' + [...ws.bytes].join('/') + ', closed ' + ws.closed);
  console.log('console errors: ' + (errors.length ? errors.join(' | ') : 'none'));
  await browser.close();
  process.exit(ws.frames > 10 ? 0 : 1);
})().catch(e => { console.error(e); process.exit(2); });
// AI: end
